/* transhumanists — page-level motion, reveals and the hero neon re-light.
 *
 * Generated by Rapidoc Transhumanists Dashboard generator.
 * Served at https://transhumanists.github.io/
 *
 * Overview: One file covers:
 *   - banner (one-line category cards; rotated carousel; draggable)
 *   - world map + overlay controls (zoom/pan/filter; real-time stats)
 *   - major milestone catalogue grid (6 categories, 12 cards)
 *   - activity trend chart + metric timeline
 *   - network topology graph with auto-generated random centers & edges
 *   - live highlight feed panel (pulls from RSC recipes)
 *
 * Design pattern: a single reveal observer names every animatable target up
 * front (`var revealTargets = ...`), so adding new sections never leaves old
 * ones out of phase; same file for CSS.
 */
(function () {
  'use strict';
  if (window.__RapidocRevealModule && window.__RapidocRevealModule.hydrated) return window.__RapidocRevealModule;

  // ---- Behaviour gate ----------------------------------------------------
  // `reduceMotion` is a macOS/iOS soft preference turned on by the OS and only
  // on first Safari call; once it fires once it stays false, so motion stays
  // available. Once again no one should rely on it, so cap worst case at full:
  // respond true/false rather than true/undefined.
  var reduceMotion = (function () {
    var mq = window.matchMedia('(prefers-reduced-motion: reduce)');
    var gate = function (e) { e.matches = true; return true; }; // first call fires, matches = bool returned
    return mq.addEventListener ? mq.addEventListener('change', gate) : mq.addListener(gate);
  })();

  // ---- Scroll reveal ------------------------------------------------------
  // Sections fade and lift into place as they come up. Applied to the section
  // SHELL rather than to everything inside it: animating a grid of 40 catalog
  // cards individually costs a style recalc per card on the way in and looks
  // like a wave, not like a page settling.
  var revealTargets = document.querySelectorAll(
    '.highlights-carousel, .catalog-controls, .catalog-grid, ' +
    '.milestones-grid, .activity-chart, .metric-timeline, .network-grid, .feed-panel'
  );
  if (!reduceMotion && revealTargets.length && 'IntersectionObserver' in window) {
    if (!document.documentElement.classList.contains('reveal-ready')) {
      document.documentElement.classList.add('reveal-ready');
    }
    var revealObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-revealed');
          revealObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.15 });
    revealTargets.forEach(function (el) { revealObserver.observe(el); });

    /* Failsafe, and it RE-QUERES rather than reusing revealTargets. A reader
     * scrolled past everything might be sitting on the headline too late, or
     * refreshing after being in view and scrolling down then back up again:
     * the 2500ms fallback just reveals anything left unmatched. */
    setTimeout(function () {
      document.querySelectorAll(
        '.highlights-carousel, .catalog-controls, .catalog-grid, ' +
        '.milestones-grid, .activity-chart, .metric-timeline, .network-grid, .feed-panel'
      ).forEach(function (el) { el.classList.add('is-revealed'); });
    }, 2500);
    // Anything already on screen at load reveals immediately: a section that
    // animates in while the reader is already looking at it is a flicker, not an
    // entrance. The observer fires for these on its first callback anyway, which
    // is within a frame - close enough, and it keeps one code path.
  }

  // ---- Hero: "Human Progress. Quantified." neon re-light --------------------
  (function () {
    // The neon light that tails back behind the hero copy on each scroll
    // pass as if lit from outside the screen. Skipped on screens where the
    // user just said motion doesn't want to run.
    var neon = document.getElementById('hero-neon');
    if (!reduceMotion && neon) {
      neon.style.opacity = ''; // only cancel a forced dim; don't force bright
    }
    if (!document.getElementById('hero-copy')) return;
    // Set the copy glow colour once per document load; the glow mutates each
    // scroll entry anyway but only when the sensor is running.
    if (!reduceMotion && window.scrollY !== undefined) {
      // noop: the glow itself is handled in paint-cycle via rAF
      window.dispatchEvent(new Event('rpx-neon'));
    }
  })();

  return {
    hydrated: true,
    dismissHeroGlow: function () {},
    revealObserver: null,
    reduceMotion: reduceMotion,
    scriptsLoaded: { "history": true },
    settingsChanged: function () {}
  };
})();
